#!/bin/bash

# Keep shared functions/variables here.

# Start the Plausible release binary with the app's env file loaded.
# install_dir/data_dir are read from the caller's global scope.
# NB: cd out of YunoHost's app_tmp_work_dirs first — it is root-owned mode
# 700 and the BEAM crashes at boot if started with a CWD the app user cannot
# traverse. Env values are alphanumeric/URL-safe (generated by this package),
# so word-splitting through env is safe.
plausible_ctl() {
    ynh_exec_as_app bash -c "set -a; source '$install_dir/env'; set +a; cd '$data_dir'; '$install_dir/app/bin/plausible' $1"
}

# Wait up to TRIES*2s for URL to answer with HTTP EXPECT.
wait_for_url() {
    local url="$1" expect="${2:-200}" tries="${3:-90}"
    for _ in $(seq 1 "$tries"); do
        [ "$(curl -s -o /dev/null -w '%{http_code}' --max-time 5 "$url")" = "$expect" ] && return 0
        sleep 2
    done
    return 1
}
